import copy
import json
import random
import tomllib
from decimal import Decimal
from pathlib import Path

_DATA = tomllib.loads((Path(__file__).parent / "data.toml").read_text())


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def simulate(days, seed):
    rng = random.Random(seed)
    demand = _DATA["demand"]
    out = []
    for _ in range(days):
        day = []
        for sku in sorted(demand):
            q = rng.randint(demand[sku]["min"], demand[sku]["max"])
            if q > 0:
                day.append((sku, q))
        out.append(day)
    return out


def _isint(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _op(blocking=False):
    def deco(f):
        def wrapper(self, *a, **k):
            snap = copy.deepcopy(self.st)
            try:
                r = f(self, *a, **k)
            except BaseException:
                self.st = snap
                raise
            self._undo = snap
            self._blocked = blocking
            self._record()
            return r
        wrapper.__name__ = f.__name__
        return wrapper
    return deco


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode,
                 late_penalty_pct=None):
        self.warehouses = list(warehouses)
        self.capacities = dict(capacities)
        self.rounding = rounding_mode
        self.late_penalty_pct = late_penalty_pct
        self.st = {
            "day": 0, "cash": opening_cash, "items": {}, "lots": {},
            "notes": [], "orders": {}, "next_order": 1, "suppliers": {},
            "suspended": {}, "shipped": {}, "returned": {}, "flags": {},
            "overdrawn": False, "shipped_by_day": {}, "held_by_day": {"0": 0},
        }
        self._undo = None
        self._blocked = False

    # ---- helpers
    @property
    def cash(self):
        return self.st["cash"]

    @property
    def day(self):
        return self.st["day"]

    def _emit(self, *n):
        self.st["notes"].append(list(n))

    def _sku(self, sku):
        if sku not in self.st["items"]:
            raise DepotError("UNKNOWN_SKU")

    def _wh(self, wh):
        if wh not in self.warehouses:
            raise DepotError("UNKNOWN_WAREHOUSE")

    def _qty(self, q):
        if not _isint(q) or q <= 0:
            raise DepotError("INVALID_QTY")

    def _units(self, sku, wh):
        return sum(q for _, q in self.st["lots"].get(sku, {}).get(wh, []))

    def _wh_total(self, wh):
        return sum(q for s in self.st["lots"].values()
                   for w, l in s.items() if w == wh for _, q in l)

    def _total(self):
        return sum(q for s in self.st["lots"].values()
                   for l in s.values() for _, q in l)

    def _record(self):
        self.st["held_by_day"][str(self.st["day"])] = self._total()

    def _cash_check(self):
        s = self.st
        if s["cash"] < 0:
            if not s["overdrawn"]:
                s["overdrawn"] = True
                self._emit("OVERDRAWN")
        else:
            s["overdrawn"] = False

    def _flag_reset(self, sku, wh):
        if self._units(sku, wh) > self.st["items"][sku][1]:
            self.st["flags"].setdefault(sku, {})[wh] = False

    def _round(self, d):
        return int(d.quantize(Decimal(1), rounding=self.rounding))

    def _add_lot(self, sku, wh, day, qty):
        self.st["lots"].setdefault(sku, {}).setdefault(wh, []).append([day, qty])

    def _take(self, sku, wh, qty):
        lots = self.st["lots"][sku][wh]
        taken = []
        while qty > 0:
            d, q = lots[0]
            t = min(q, qty)
            taken.append([d, t])
            qty -= t
            if t == q:
                lots.pop(0)
            else:
                lots[0][1] -= t
        return taken

    # ---- inventory
    @_op()
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        if sku in self.st["items"]:
            raise DepotError("DUPLICATE_SKU")
        if not _isint(unit_cost) or unit_cost <= 0 or not _isint(reorder_level) \
                or reorder_level < 0:
            raise DepotError("INVALID_ITEM")
        if shelf_life_days is not None and (not _isint(shelf_life_days)
                                            or shelf_life_days < 1):
            raise DepotError("INVALID_SHELF_LIFE")
        self.st["items"][sku] = [unit_cost, reorder_level, shelf_life_days]

    @_op()
    def receive(self, sku, qty, wh):
        self._receive(sku, qty, wh)

    def _receive(self, sku, qty, wh):
        self._sku(sku)
        self._wh(wh)
        self._qty(qty)
        if self.st["cash"] < 0:
            raise DepotError("OVERDRAWN")
        if self._wh_total(wh) + qty > self.capacities[wh]:
            raise DepotError("CAPACITY")
        cost = self.st["items"][sku][0] * qty
        if self.st["cash"] - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self.st["cash"] -= cost
        self._add_lot(sku, wh, self.st["day"], qty)
        self._flag_reset(sku, wh)

    @_op()
    def receive_bulk(self, receipts):
        for sku, qty, wh in receipts:
            self._receive(sku, qty, wh)

    @_op()
    def ship(self, sku, qty, wh, price):
        self._sku(sku)
        self._wh(wh)
        self._qty(qty)
        if not _isint(price) or price < 0:
            raise DepotError("INVALID_PRICE")
        if self._units(sku, wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        self._take(sku, wh, qty)
        gross = Decimal(price * qty)
        if qty >= _DATA["bulk_threshold"]:
            gross = gross * (100 - _DATA["bulk_discount_pct"]) / 100
        self.st["cash"] += self._round(gross)
        s = self.st
        s["shipped"][sku] = s["shipped"].get(sku, 0) + qty
        k = str(s["day"])
        s["shipped_by_day"][k] = s["shipped_by_day"].get(k, 0) + qty
        level = s["items"][sku][1]
        flags = s["flags"].setdefault(sku, {})
        if self._units(sku, wh) <= level and not flags.get(wh):
            flags[wh] = True
            self._emit("REORDER", sku, wh)
        self._cash_check()

    def list_price(self, sku):
        self._sku(sku)
        d = Decimal(self.st["items"][sku][0]) * (1 + Decimal(str(_DATA["markup"])))
        return self._round(d)

    @_op()
    def transfer(self, sku, qty, from_wh, to_wh):
        self._sku(sku)
        self._wh(from_wh)
        self._wh(to_wh)
        self._qty(qty)
        if self._units(sku, from_wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        if from_wh != to_wh and self._wh_total(to_wh) + qty > self.capacities[to_wh]:
            raise DepotError("CAPACITY")
        taken = self._take(sku, from_wh, qty)
        dest = self.st["lots"].setdefault(sku, {}).setdefault(to_wh, [])
        dest.extend(taken)
        dest.sort(key=lambda l: l[0])
        self.st["cash"] -= _DATA["transfer_credit_cents_per_unit"] * qty
        level = self.st["items"][sku][1]
        flags = self.st["flags"].setdefault(sku, {})
        if from_wh != to_wh and self._units(sku, from_wh) <= level \
                and not flags.get(from_wh):
            flags[from_wh] = True
            self._emit("REORDER", sku, from_wh)
        self._flag_reset(sku, to_wh)
        self._cash_check()

    @_op(blocking=True)
    def advance_day(self):
        s = self.st
        s["day"] += 1
        s["cash"] -= _DATA["storage_cents_per_unit_day"] * self._total()
        for sku in sorted(s["lots"]):
            shelf = s["items"][sku][2]
            if shelf is None:
                continue
            for wh in sorted(s["lots"][sku]):
                lots = s["lots"][sku][wh]
                gone = sum(q for d, q in lots if s["day"] - d > shelf)
                if gone:
                    lots[:] = [l for l in lots if s["day"] - l[0] <= shelf]
                    self._emit("EXPIRY", sku, wh, gone)
                    self._flag_reset(sku, wh)
        self._cash_check()

    def notifications(self):
        return [tuple(n) for n in self.st["notes"]]

    def stock(self, sku, wh=None):
        self._sku(sku)
        if wh is not None:
            self._wh(wh)
            return self._units(sku, wh)
        return sum(self._units(sku, w) for w in self.warehouses)

    def report(self):
        rows = []
        for sku, whs in self.st["lots"].items():
            for wh in whs:
                u = self._units(sku, wh)
                if u:
                    rows.append((sku, wh, u, u * self.st["items"][sku][0]))
        return sorted(rows, key=lambda r: (r[0], r[1]))

    @_op()
    def audit(self, counts):
        if not counts:
            raise DepotError("EMPTY_AUDIT")
        for sku, wh in counts:
            self._sku(sku)
            self._wh(wh)
        for (sku, wh) in sorted(counts):
            led = self._units(sku, wh)
            if led != counts[(sku, wh)]:
                self._emit("AUDIT_MISMATCH", sku, wh, led, counts[(sku, wh)])

    @_op()
    def return_goods(self, sku, qty, wh, price):
        self._sku(sku)
        self._wh(wh)
        self._qty(qty)
        if not _isint(price) or price < 0:
            raise DepotError("INVALID_PRICE")
        s = self.st
        if qty > s["shipped"].get(sku, 0) - s["returned"].get(sku, 0):
            raise DepotError("RETURN_EXCEEDS")
        if s["items"][sku][2] is not None:
            raise DepotError("RETURN_POLICY_UNDECIDED")
        if self._wh_total(wh) + qty > self.capacities[wh]:
            raise DepotError("CAPACITY")
        self._add_lot(sku, wh, s["day"], qty)
        s["returned"][sku] = s["returned"].get(sku, 0) + qty
        s["cash"] -= price * qty
        self._flag_reset(sku, wh)
        self._cash_check()

    def turnover(self, start_day, end_day):
        s = self.st
        days = [d for d in range(start_day, end_day + 1) if str(d) in s["held_by_day"]]
        if not days:
            return None
        avg = Decimal(sum(s["held_by_day"][str(d)] for d in days)) / len(days)
        if avg == 0:
            return None
        shipped = sum(s["shipped_by_day"].get(str(d), 0)
                      for d in range(start_day, end_day + 1))
        return float(Decimal(shipped) / avg)

    # ---- suppliers
    def _rel_update(self, sup, new):
        s = self.st
        new = max(0, min(5, new))
        s["suppliers"][sup] = new
        if new <= 1:
            if not s["suspended"].get(sup):
                s["suspended"][sup] = True
                self._emit("SUPPLIER_SUSPENDED", sup)
        else:
            s["suspended"][sup] = False

    @_op()
    def place_order(self, supplier, sku, qty, due_day):
        self._sku(sku)
        self._qty(qty)
        s = self.st
        if s["suspended"].get(supplier):
            raise DepotError("SUPPLIER_SUSPENDED")
        s["suppliers"].setdefault(supplier, 3)
        oid = s["next_order"]
        s["next_order"] += 1
        s["orders"][str(oid)] = {"supplier": supplier, "sku": sku, "qty": qty,
                                 "due": due_day, "done": False}
        return oid

    @_op()
    def deliver(self, order_id, day):
        o = self.st["orders"].get(str(order_id))
        if o is None:
            raise DepotError("UNKNOWN_ORDER")
        if o["done"]:
            raise DepotError("ALREADY_DELIVERED")
        late = day > o["due"]
        if late and self.late_penalty_pct is None:
            raise DepotError("LATE_PENALTY_UNDECIDED")
        o["done"] = True
        sup = o["supplier"]
        self._rel_update(sup, self.st["suppliers"][sup] + (-1 if late else 1))

    def reliability(self, supplier):
        if supplier not in self.st["suppliers"]:
            raise DepotError("UNKNOWN_SUPPLIER")
        return self.st["suppliers"][supplier]

    @_op()
    def reinstate(self, supplier):
        if supplier not in self.st["suppliers"]:
            raise DepotError("UNKNOWN_SUPPLIER")
        self.st["suppliers"][supplier] = 2
        self.st["suspended"][supplier] = False

    # ---- persistence / undo
    def save(self):
        return json.dumps({"version": 1, "state": self.st})

    @_op()
    def load(self, s):
        try:
            d = json.loads(s)
            if not isinstance(d, dict) or d.get("version") != 1 \
                    or not isinstance(d.get("state"), dict):
                raise ValueError
            st = d["state"]
            if set(st) != set(self.st):
                raise ValueError
            for k, v in st.items():
                if type(v) is not type(self.st[k]):
                    raise ValueError
            for sku, whs in st["lots"].items():
                if sku not in st["items"]:
                    raise ValueError
                for wh, lots in whs.items():
                    if wh not in self.warehouses:
                        raise ValueError
                    for d_, q in lots:
                        if not _isint(d_) or not _isint(q):
                            raise ValueError
            for n in st["notes"]:
                if not isinstance(n, list) or not n:
                    raise ValueError
        except Exception:
            raise DepotError("BAD_SAVE")
        self.st = copy.deepcopy(st)

    def undo(self):
        if self._blocked:
            raise DepotError("UNDO_BLOCKED")
        if self._undo is None:
            raise DepotError("NOTHING_TO_UNDO")
        self.st = self._undo
        self._undo = None
